1	/**
2	 * The run-scoped cache of immutable evidence (docs/PRD_VIEWER_UX.md 7): worker and candidate results (`results/<lane>/<k>`)
3	 * and recorded reviews (`reviews/<n>`) never change once served, so each URI is read once and kept for as long as the page
4	 * lives, shared by the run page's Now banner, the node pages and their attempt strips. Only the run detail, its events and
5	 * its inputs poll. A URI that answered 404 or failed is asked again when the caller's `stamp` changes: a Refresh, or new
6	 * events, after which a result that did not exist yet may.
7	 */
8	import { useCallback, useEffect, useMemo, useState, useSyncExternalStore } from 'react'
9	import {
10	  fetchReviewResult, fetchWorkerResult, NOT_RECORDED, orNotRecorded, ProjectsApiError, scopedResultPath, scopedReviewPath,
11	  type ReviewResult, type RunScope, type WorkerResult,
12	} from './api.ts'
13	import type { Resource } from './useResource.ts'
14	
15	type Entry =
16	  | { status: 'ready'; value: unknown }
17	  /** A 404: not there (yet); asked again under another stamp. */
18	  | { status: 'absent'; error: unknown; stamp: string }
19	  | { status: 'failed'; error: unknown; stamp: string }
20	
21	/** Enough for every attempt of a long run's steps; the oldest entries go first. */
22	const CACHE_LIMIT = 400
23	const cache = new Map<string, Entry>()
24	const inflight = new Set<string>()
25	const listeners = new Set<() => void>()
26	let version = 0
27	
28	function settle(key: string, entry: Entry) {
29	  cache.delete(key)
30	  cache.set(key, entry)
31	  if (cache.size > CACHE_LIMIT) cache.delete(cache.keys().next().value!)
32	  version += 1
33	  listeners.forEach(listener => listener())
34	}
35	
36	function subscribe(listener: () => void) {
37	  listeners.add(listener)
38	  return () => { listeners.delete(listener) }
39	}
40	
41	type Fetcher = (uri: string) => Promise<unknown>
42	
43	/** Fetches every URI the cache does not hold under this stamp; re-renders whenever any entry settles. */
44	function useCached(kind: 'result' | 'review', uris: readonly string[], stamp: string, fetcher: Fetcher): (uri: string) => Entry | undefined {
45	  const current = useSyncExternalStore(subscribe, () => version, () => version)
46	  const key = uris.join('\n')
47	  useEffect(() => {
48	    for (const uri of key === '' ? [] : key.split('\n')) {
49	      const cacheKey = `${kind}:${uri}`
50	      const known = cache.get(cacheKey)
51	      if (inflight.has(cacheKey) || (known && (known.status === 'ready' || known.stamp === stamp))) continue
52	      inflight.add(cacheKey)
53	      fetcher(uri).then(
54	        value => settle(cacheKey, { status: 'ready', value }),
55	        (error: unknown) => settle(cacheKey, error instanceof ProjectsApiError && error.notFound ? { status: 'absent', error, stamp } : { status: 'failed', error, stamp }),
56	      ).finally(() => inflight.delete(cacheKey))
57	    }
58	    // The fetcher is rebuilt per render; the scope it closes over is part of every URI.
59	    // eslint-disable-next-line react-hooks/exhaustive-deps
60	  }, [kind, key, stamp])
61	  // `current` re-reads the cache whenever an entry settles.
62	  // eslint-disable-next-line react-hooks/exhaustive-deps
63	  return useCallback((uri: string) => cache.get(`${kind}:${uri}`), [kind, current])
64	}
65	
66	/** A result URI outside this run's results route is never fetched; it reads as absent. */
67	function resultFetcher(scope: RunScope): Fetcher {
68	  return uri => {
69	    const path = scopedResultPath(scope, uri)
70	    if (path === null) return Promise.reject(new ProjectsApiError('http', `The result link ${uri} is outside this run's results route.`, uri, { status: 404 }))
71	    return fetchWorkerResult(scope, path)
72	  }
73	}
74	
75	/**
76	 * Several results at once: those that loaded, and how many were never answered yet. A result that answered 404 counts as
77	 * absent, not as loading; another failure counts as settled and is asked again under the next stamp.
78	 */
79	export function useRunResults(scope: RunScope, uris: readonly string[], stamp: string): { results: ReadonlyMap<string, WorkerResult>; pending: number } {
80	  const read = useCached('result', uris, stamp, resultFetcher(scope))
81	  const key = uris.join('\n')
82	  return useMemo(() => {
83	    const results = new Map<string, WorkerResult>()
84	    let pending = 0
85	    for (const uri of key === '' ? [] : key.split('\n')) {
86	      const entry = read(uri)
87	      if (entry?.status === 'ready') results.set(uri, entry.value as WorkerResult)
88	      else if (!entry) pending += 1
89	    }
90	    return { results, pending }
91	  }, [key, read])
92	}
93	
94	/** A settled failure stays shown while a later stamp asks again, like a failed background reload. */
95	function asResource<T>(entry: Entry | undefined): Resource<T> {
96	  if (entry?.status === 'ready') return { status: 'ready', data: entry.value as T }
97	  if (entry) return { status: 'error', error: entry.error }
98	  return { status: 'loading' }
99	}
100	
101	/** One result, as a resource: a node's own result, where a 404 is an error to show rather than an absence. `reload` asks again. */
102	export function useRunResult(scope: RunScope, uri: string | null, stamp: string): { state: Resource<WorkerResult>; reload: () => void } {
103	  const [retry, setRetry] = useState(0)
104	  const full = `${stamp}:${retry}`
105	  const read = useCached('result', uri === null ? [] : [uri], full, resultFetcher(scope))
106	  const reload = useCallback(() => setRetry(previous => previous + 1), [])
107	  return { state: uri === null ? { status: 'idle' } : asResource<WorkerResult>(read(uri)), reload }
108	}
109	
110	/** The recorded review, read once per URI; a run whose export predates reviews has none (null). */
111	export function useRunReview(scope: RunScope, uri: string | null, stamp: string): Resource<ReviewResult | null> {
112	  const fetcher: Fetcher = reviewUri => {
113	    const path = scopedReviewPath(scope, reviewUri)
